// Igual que formularioPublico, pero quitando de los campos "unica" las opciones que ya se han usado.
async function formularioPublicoDisponible(env, f, conContenido) {
  const pub = formularioPublico(f, conContenido);
  if (!pub.campos.length) return pub;
  // Personas invitadas desde el panel (vigentes): se suman a las opciones fijas del campo.
  pub.campos = await aplicarInvitadosFormulario(env, f, camposConAltaPorDefecto(f.slug, pub.campos));
  const usadas = await opcionesUsadasFormulario(env, f, pub.campos);
  pub.campos = pub.campos.map((c) => {
    const u = usadas.get(c.id);
    // alias_usuarios (opción -> nombre de usuario) es interno del panel: no se entrega a los visitantes.
    const { alias_usuarios: _alias, ...publico } = c;
    return u && u.size ? { ...publico, opciones: c.opciones.filter((o) => !u.has(normalizarOpcionUnica(o))) } : publico;
  });
  return pub;
}

// ---------- Invitaciones: personas añadidas a un formulario SIN editarlo ----------
// En vez de abrir el editor del formulario y escribir el nombre en su lista de opciones, el admin invita a
// la persona desde Solicitudes > Formularios > (formulario) > "Personas invitadas". Su nombre sale en la
// lista desplegable del formulario público durante N días (7 por defecto) y desaparece solo: al caducar
// o cuando esa persona responde (cada invitación se usa una sola vez). Se aplica a los campos
// desplegable/opción con "invitaciones" o "alta_usuario" (p. ej. los nombres del formulario de incorporación).
// Las fechas se guardan como 'YYYY-MM-DD HH:MM:SS' (UTC) y se comparan como texto, igual en D1 y PostgreSQL.
const FORMULARIO_INVITACION_DIAS_DEFECTO = 7;
const FORMULARIO_INVITACION_DIAS_MAX = 365;
const FORMULARIO_INVITACION_MAX_POR_VEZ = 100;
function fechaSqlFormulario(ms) { return new Date(ms).toISOString().slice(0, 19).replace("T", " "); }
function ahoraSqlFormulario() { return fechaSqlFormulario(Date.now()); }
// Devuelve { dias } (0 = no caduca) o { error }. Sin valor, 7 días.
function normalizarDiasInvitacionFormulario(v) {
  if (v === undefined || v === null || v === "") return { dias: FORMULARIO_INVITACION_DIAS_DEFECTO };
  const n = Number(v);
  if (!Number.isInteger(n) || n < 0 || n > FORMULARIO_INVITACION_DIAS_MAX) {
    return { error: `La caducidad debe estar entre 0 (no caduca) y ${FORMULARIO_INVITACION_DIAS_MAX} días` };
  }
  return { dias: n };
}
function expiraInvitacionFormulario(dias) { return dias > 0 ? fechaSqlFormulario(Date.now() + dias * 86400000) : null; }
function campoAdmiteInvitaciones(c) {
  return !!c && (c.tipo === "desplegable" || c.tipo === "opcion")
    && (c.invitaciones === true || FORMULARIO_ALTA_ROLES.includes(String(c.alta_usuario || "")));
}
// Deja la persona en el formato de siempre. En los campos que crean usuario: "Nombre - Equipo", "Nombre – Equipo"
// o "Nombre—Equipo" pasan a "Nombre — Equipo", y los equipos se separan con " & " (no toca guiones de nombres como "Ana-María").
function normalizarPersonaInvitacionFormulario(texto, campo) {
  let t = String(texto || "").replace(/\s+/g, " ").trim();
  if (!campo || !campo.alta_usuario) return t;
  t = t.replace(/\s*[—–―]\s*|\s+-{1,2}\s+/, " — ");
  const i = t.indexOf(" — ");
  if (i < 0) return t;
  const nombre = t.slice(0, i).trim();
  const equipos = t.slice(i + 3).replace(/\s*&\s*/g, " & ").trim();
  return equipos ? `${nombre} — ${equipos}` : nombre;
}
async function invitadosActivosFormulario(env, formularioId) {
  const { results } = await env.DB.prepare(
    "SELECT campo_id, opcion FROM formularios_invitados WHERE formulario_id = ? AND (expira_at IS NULL OR expira_at > ?) ORDER BY id"
  ).bind(formularioId, ahoraSqlFormulario()).all();
  return results || [];
}
// Suma a los campos que admiten invitaciones las personas invitadas vigentes. Cada invitación se usa una sola
// vez (el campo pasa a "unica") y "invitaciones" avisa al formulario público de que puede mostrar el aviso de caducidad.
async function aplicarInvitadosFormulario(env, f, campos) {
  if (!campos.some(campoAdmiteInvitaciones)) return campos;
  let activos = [];
  try { activos = await invitadosActivosFormulario(env, f.id); }
  catch (err) { console.error("[formularios/invitados]", err); } // sin la tabla (migración sin aplicar) el formulario sigue con sus opciones fijas
  return campos.map((c) => {
    if (!campoAdmiteInvitaciones(c)) return c;
    const opciones = [...(c.opciones || [])];
    const vistas = new Set(opciones.map(normalizarOpcionUnica));
    for (const i of activos) {
      if (i.campo_id !== c.id) continue;
      const k = normalizarOpcionUnica(i.opcion);
      if (!vistas.has(k)) { vistas.add(k); opciones.push(i.opcion); }
    }
    return { ...c, opciones, unica: true, invitaciones: true };
  });
}
// Para el panel: todas las invitaciones del formulario con su estado (activa | caducada | usada).
async function listarInvitadosFormulario(env, f, campos) {
  const camposInv = campos.filter(campoAdmiteInvitaciones);
  if (!camposInv.length) return [];
  const { results } = await env.DB.prepare(
    "SELECT id, campo_id, opcion, expira_at, creado_por, created_at FROM formularios_invitados WHERE formulario_id = ? ORDER BY id DESC LIMIT 1000"
  ).bind(f.id).all();
  const filas = (results || []).filter((i) => camposInv.some((c) => c.id === i.campo_id));
  if (!filas.length) return [];
  const usadas = await opcionesUsadasFormulario(env, f, camposInv.map((c) => ({
    ...c, unica: true, opciones: filas.filter((i) => i.campo_id === c.id).map((i) => i.opcion),
  })));
  const ahora = ahoraSqlFormulario();
  return filas.map((i) => {
    const u = usadas.get(i.campo_id);
    const usada = !!(u && u.has(normalizarOpcionUnica(i.opcion)));
    const caducada = !usada && !!i.expira_at && i.expira_at <= ahora;
    return { ...i, estado: usada ? "usada" : caducada ? "caducada" : "activa" };
  });
}
// ---------- Alta automática de usuarios desde un formulario ----------
// Un campo desplegable/opción con "alta_usuario" (redactor | fotografo) es una plantilla de
// nombres y equipos ("Nombre — Equipo1 & Equipo2"). Al enviar el formulario con una de esas
// opciones se crea el usuario (usuario y contraseña) con ese nombre, equipo(s) y rol, y se le
// entrega la contraseña en pantalla y por correo (el que escribe en el formulario).
// Si luego se elimina el usuario, se borra también su respuesta (y la opción vuelve a la lista).
const FORMULARIO_ALTA_ROLES = ["redactor", "fotografo"];
const FORMULARIO_CATEGORIA_FIJA_ETIQUETA = { arbitraje: "Arbitraje", jurisdiccion: "Jurisdicción deportiva" };
function formularioClaveNombreUsuario(t) {
  // Sin el paréntesis final (p. ej. un teléfono), sin tildes ni mayúsculas.
  return normalizarOpcionUnica(String(t || "").replace(/\s*\([^)]*\)\s*$/, ""));
}
function etiquetaUsuarioFormulario(u) {
  const nombre = String((u && u.nombre) || "").trim();
  const equipos = parsearEquipos(u && u.equipo);
  const cats = parsearCategoriasFijas(u && u.categorias_fijas).map((c) => FORMULARIO_CATEGORIA_FIJA_ETIQUETA[c] || c);
  const detalle = [...equipos, ...cats].join(" & ");
  return detalle ? `${nombre} — ${detalle}` : nombre;
}
// "Jose Morales — Arbitraje" -> { nombre, equipos: [], categorias_fijas: ["arbitraje"] }
function datosUsuarioDesdeOpcionFormulario(valor) {
  const t = String(valor || "").replace(/\s*\([^)]*\)\s*$/, "").trim();
  const i = t.indexOf(" — ");
  const nombre = (i >= 0 ? t.slice(0, i) : t).trim();
  const partes = i >= 0 ? t.slice(i + 3).split(/\s*&\s*/).map((x) => x.trim()).filter(Boolean) : [];
  const categorias = [];
  const equipos = [];
  for (const p of partes) {
    const k = normalizarOpcionUnica(p);
    if (k === "arbitraje") categorias.push("arbitraje");
    else if (k === "jurisprudencia" || k.startsWith("jurisdiccion")) categorias.push("jurisdiccion");
    else equipos.push(p);
  }
  return { nombre, equipos: equipos.slice(0, 3), categorias_fijas: [...new Set(categorias)] };
}
function usernameBaseFormulario(nombre) {
  const s = normalizarOpcionUnica(nombre).replace(/[^a-z0-9]+/g, ".").replace(/^\.+|\.+$/g, "").slice(0, 24);
  return s || "usuario";
}
async function usernameLibreFormulario(env, nombre, equipos) {
  const base = usernameBaseFormulario(nombre);
  const club = equipos.length ? normalizarOpcionUnica(equipos[0]).replace(/[^a-z0-9]+/g, "").slice(0, 12) : "";
  const candidatos = [base, ...(club ? [`${base}_${club}`] : [])];
  for (let n = 2; n < 60; n++) candidatos.push(`${base}${n}`);
  for (const c of candidatos) {
    const row = await env.DB.prepare("SELECT id FROM users WHERE username = ?").bind(c).first();
    if (!row) return c;
  }
  return `${base}${Date.now().toString(36)}`;
}
// ¿Esta opción de la lista corresponde a este usuario? Tres niveles, de más a menos estricto:
//  1) alias explícito (campo.alias_usuarios): decide solo, es la forma segura para quien tiene otro nombre;
//  2) mismo nombre y equipo/categoría exactos (tildes, mayúsculas y teléfono entre paréntesis ignorados);
//  3) mismo nombre y al menos un equipo o categoría en común (p. ej. alguien con un equipo más o menos).
function opcionCoincideConUsuarioFormulario(opcion, u, alias) {
  const clave = formularioClaveNombreUsuario(opcion);
  for (const [k, v] of Object.entries(alias || {})) {
    if (formularioClaveNombreUsuario(k) === clave) return String(v).toLowerCase() === String(u.username || "").toLowerCase();
  }
  if (clave === formularioClaveNombreUsuario(etiquetaUsuarioFormulario(u))) return true;
  const d = datosUsuarioDesdeOpcionFormulario(opcion);
  if (!d.nombre || normalizarOpcionUnica(d.nombre) !== normalizarOpcionUnica(u.nombre)) return false;
  const equipos = parsearEquipos(u.equipo).map(normalizarOpcionUnica);
  const cats = parsearCategoriasFijas(u.categorias_fijas);
  return d.equipos.some((e) => equipos.includes(normalizarOpcionUnica(e))) || d.categorias_fijas.some((c) => cats.includes(c));
}
// Nombres y apellidos de colaboradores: la primera letra de cada palabra siempre va en mayúscula
// ("juan garcía-lópez" -> "Juan García-López"). Solo se sube la inicial: el resto se respeta tal cual
// (McDonald, O'Brien...), y las partículas de en medio ("de", "del", "la", "van"...) se dejan como estén
// escritas ("Juan de la Cruz"). Se aplica al crear/editar usuarios, al editar el perfil propio y en el alta
// desde el formulario de incorporación, así que el nombre queda igual en firmas, créditos y perfil público.
const PARTICULAS_NOMBRE_PROPIO = new Set(["de", "del", "dels", "la", "las", "los", "el", "y", "e", "i", "da", "das", "do", "dos", "di", "van", "von", "der", "den"]);
function capitalizarNombrePropio(texto) {
  const limpio = String(texto == null ? "" : texto).replace(/\s+/g, " ").trim();
  if (!limpio) return "";
  return limpio.split(" ").map((palabra, i) => {
    if (i > 0 && PARTICULAS_NOMBRE_PROPIO.has(palabra.toLowerCase())) return palabra;
    return palabra.replace(/(^|-)(\p{L})/gu, (_, sep, letra) => sep + letra.toLocaleUpperCase("es"));
  }).join(" ");
}
// ---------- Excepción: firmar solo con el nombre (sin apellidos) ----------
// Redactores y fotógrafos deben tener nombre y apellidos, pero hay quien prefiere no
// publicar su apellido (privacidad). Un Responsable puede marcar esa excepción desde
// Usuarios (users.sin_apellidos = 1): a esa persona ya no se le exigen apellidos ni en
// el panel ni en el servidor. La columna se crea sola la primera vez que se usa.
let _columnaSinApellidosLista = null;
async function asegurarColumnaSinApellidos(env) {
  if (_columnaSinApellidosLista) return _columnaSinApellidosLista;
  _columnaSinApellidosLista = (async () => {
    try {
      await env.DB.prepare("SELECT sin_apellidos FROM users LIMIT 1").first();
      return true;
    } catch (err) {
      if (!/no such column|does not exist|undefined column/i.test(String((err && err.message) || err))) throw err;
    }
    console.warn("[SIN APELLIDOS] Falta users.sin_apellidos: se crea ahora (migración automática).");
    try {
      await env.DB.prepare("ALTER TABLE users ADD COLUMN sin_apellidos INTEGER NOT NULL DEFAULT 0").run();
    } catch (err) {
      if (!/duplicate column|already exists/i.test(String((err && err.message) || err))) throw err;
    }
    return true;
  })();
  _columnaSinApellidosLista.catch(() => { _columnaSinApellidosLista = null; });
  return _columnaSinApellidosLista;
}
// ---------- Colaborador anónimo ----------
// users.anonimo = 1: lo que publica esa persona se muestra SIN su nombre ("Colaborador anónimo"):
// ni en la web pública, ni en RSS, ni para el resto de colaboradores del panel. Solo los admins
// (Responsables) siguen viendo quién es, y la propia persona ve lo suyo con su nombre. No cambia lo
// guardado en la base (autor_id/autor_nombre siguen siendo los reales): se oculta al RESPONDER, en
// un único sitio (anonimizarRespuesta, que envuelve fetch), para que ningún endpoint se olvide.
const NOMBRE_AUTOR_ANONIMO = "Colaborador anónimo";
let _columnaAnonimoLista = null;
async function asegurarColumnaAnonimo(env) {
  if (_columnaAnonimoLista) return _columnaAnonimoLista;
  _columnaAnonimoLista = (async () => {
    try {
      await env.DB.prepare("SELECT anonimo FROM users LIMIT 1").first();
      return true;
    } catch (err) {
      if (!/no such column|does not exist|undefined column/i.test(String((err && err.message) || err))) throw err;
    }
    console.warn("[ANONIMO] Falta users.anonimo: se crea ahora (migración automática).");
    try {
      await env.DB.prepare("ALTER TABLE users ADD COLUMN anonimo INTEGER NOT NULL DEFAULT 0").run();
    } catch (err) {
      if (!/duplicate column|already exists/i.test(String((err && err.message) || err))) throw err;
    }
    return true;
  })();
  _columnaAnonimoLista.catch(() => { _columnaAnonimoLista = null; });
  return _columnaAnonimoLista;
}

// Cuentas anónimas (ids y nombres). Caché de 30 s por isolate; si la columna aún no existe o falla
// la consulta, no hay anónimos (nunca rompe una lectura pública).
async function cargarAnonimos(env) {
  try {
    return await memoCorta("anonimos:lista", 30000, async () => {
      try {
        const { results } = await env.DB.prepare("SELECT id, nombre FROM users WHERE anonimo = 1").all();
        const ids = new Set(); const nombres = new Set();
        for (const r of results || []) { ids.add(Number(r.id)); if (r.nombre) nombres.add(String(r.nombre)); }
        return { ids, nombres };
      } catch (err) {
        if (!/no such column|does not exist|undefined column/i.test(String((err && err.message) || err))) console.error("[ANONIMO] cargarAnonimos:", err && err.message);
        return { ids: new Set(), nombres: new Set() };
      }
    });
  } catch { return { ids: new Set(), nombres: new Set() }; }
}

function ocultarAnonimosEnJson(nodo, anon, propio) {
  if (Array.isArray(nodo)) { for (const x of nodo) ocultarAnonimosEnJson(x, anon, propio); return; }
  if (!nodo || typeof nodo !== "object") return;
  const esAjeno = (id) => id != null && anon.ids.has(Number(id)) && Number(id) !== propio.uid;
  const nombreAnonimoAjeno = (n) => typeof n === "string" && anon.nombres.has(n) && n !== propio.nombre;
  for (const [kId, kNombre] of [["autor_id", "autor_nombre"], ["coautor_id", "coautor_nombre"]]) {
    if (!(kNombre in nodo) && !(kId in nodo)) continue;
    if (esAjeno(nodo[kId])) { nodo[kId] = null; nodo[kNombre] = NOMBRE_AUTOR_ANONIMO; }
    else if ((nodo[kId] == null) && nombreAnonimoAjeno(nodo[kNombre])) nodo[kNombre] = NOMBRE_AUTOR_ANONIMO;
  }
  if (nombreAnonimoAjeno(nodo.credito)) nodo.credito = NOMBRE_AUTOR_ANONIMO;
  if (Array.isArray(nodo.firmantes)) {
    const vistos = new Set();
    nodo.firmantes = nodo.firmantes.map((f) => (f && (esAjeno(f.id) || (f.id == null && nombreAnonimoAjeno(f.nombre))) ? { id: null, nombre: NOMBRE_AUTOR_ANONIMO } : f))
      .filter((f) => { const k = f && f.id == null ? "n:" + f.nombre : "i:" + (f && f.id); if (vistos.has(k)) return false; vistos.add(k); return true; });
  }
  for (const k of Object.keys(nodo)) { const v = nodo[k]; if (v && typeof v === "object") ocultarAnonimosEnJson(v, anon, propio); }
}

// Perfil público (y RSS) de una cuenta anónima: no existe para nadie salvo admins y ella misma.
// Se resuelve ANTES de ejecutar el endpoint (no hace falta ni consultarlo).
async function bloquearPerfilAnonimo(request, env) {
  try {
    if (request.method !== "GET") return null;
    const m = new URL(request.url).pathname.match(/^\/(?:api\/autores|rss\/autor)\/(\d+)(?:\.xml)?$/);
    if (!m) return null;
    const anon = await cargarAnonimos(env);
    const id = Number(m[1]);
    if (!anon.ids.has(id)) return null;
    if ((request.headers.get("Authorization") || "").startsWith("Bearer ")) {
      const payload = await requireAuth(request, env);
      if (payload && (payload.rol === "admin" || Number(payload.uid) === id)) return null;
    }
    return json({ error: "Autor no encontrado" }, 404);
  } catch (err) {
    console.error("[ANONIMO] bloquearPerfilAnonimo:", err && err.message);
    return null;
  }
}

async function anonimizarRespuesta(request, env, resp) {
  try {
    if (request.method !== "GET" || !resp || resp.status !== 200) return resp;
    const path = new URL(request.url).pathname;
    const esApi = path.startsWith("/api/") && !/^\/api\/(me|users|internal)(\/|$)/.test(path);
    const esRss = path.startsWith("/rss");
    if (!esApi && !esRss) return resp;
    const anon = await cargarAnonimos(env);
    if (!anon.ids.size) return resp;
    // Quien mira: un admin lo ve todo; un colaborador anónimo ve lo suyo con su nombre.
    let propio = { uid: null, nombre: null };
    if ((request.headers.get("Authorization") || "").startsWith("Bearer ")) {
      const payload = await requireAuth(request, env);
      if (payload) {
        if (payload.rol === "admin") return resp;
        propio = { uid: Number(payload.uid), nombre: payload.nombre || null };
      }
    }
    const ct = resp.headers.get("Content-Type") || "";
    const esJson = /json/i.test(ct);
    const esXml = /xml/i.test(ct);
    if (!esJson && !esXml) return resp;
    const texto = await resp.text();
    const reconstruir = (t) => { const h = new Headers(resp.headers); h.delete("Content-Length"); return new Response(t, { status: resp.status, statusText: resp.statusText, headers: h }); };
    if (esXml) {
      let t = texto;
      for (const n of anon.nombres) {
        if (n === propio.nombre) continue;
        t = t.split(`<dc:creator>${escaparXml(n)}</dc:creator>`).join(`<dc:creator>${NOMBRE_AUTOR_ANONIMO}</dc:creator>`);
      }
      return reconstruir(t);
    }
    // Sin ningún id ni nombre anónimo en el texto no hay nada que tocar (camino rápido).
    let hay = false;
    for (const id of anon.ids) { if (texto.includes(`"autor_id":${id}`) || texto.includes(`"coautor_id":${id}`) || texto.includes(`"id":${id}`)) { hay = true; break; } }
    if (!hay) for (const n of anon.nombres) { if (texto.includes(JSON.stringify(n))) { hay = true; break; } }
    if (!hay) return reconstruir(texto);
    let datos;
    try { datos = JSON.parse(texto); } catch { return reconstruir(texto); }
    if (path === "/api/autores" && datos && Array.isArray(datos.autores)) {
      datos.autores = datos.autores.filter((a) => !(a && anon.ids.has(Number(a.id)) && Number(a.id) !== propio.uid));
    }
    ocultarAnonimosEnJson(datos, anon, propio);
    return reconstruir(JSON.stringify(datos));
  } catch (err) {
    console.error("[ANONIMO] anonimizarRespuesta:", err && err.message);
    return resp;
  }
}

async function usuarioSinApellidos(env, uid) {
  try {
    await asegurarColumnaSinApellidos(env);
    const fila = await env.DB.prepare("SELECT sin_apellidos FROM users WHERE id = ?").bind(uid).first();
    return !!(fila && Number(fila.sin_apellidos) === 1);
  } catch (err) {
    return false;
  }
}
// Crea el usuario de la opción elegida. Devuelve { cuenta } (cuenta=null si esa persona ya tenía usuario).
async function crearUsuarioDesdeFormulario(env, { opcion, rol, email, alias }) {
  const d = datosUsuarioDesdeOpcionFormulario(opcion);
  if (!d.nombre || !FORMULARIO_ALTA_ROLES.includes(rol)) return { cuenta: null };
  const { results } = await env.DB.prepare("SELECT id, username, nombre, rol, equipo, categorias_fijas FROM users").all();
  const todos = results || [];
  // Con alias explícito, la persona ya tiene su usuario (de cualquier rol): no se crea otro.
  const clave = formularioClaveNombreUsuario(opcion);
  const enAlias = Object.entries(alias || {}).find(([k]) => formularioClaveNombreUsuario(k) === clave);
  if (enAlias && todos.some((u) => String(u.username).toLowerCase() === String(enAlias[1]).toLowerCase())) return { cuenta: null, yaExistia: true };
  if (!enAlias && todos.some((u) => u.rol === rol && opcionCoincideConUsuarioFormulario(opcion, u, alias))) return { cuenta: null, yaExistia: true };
  d.nombre = capitalizarNombrePropio(d.nombre);
  const { error, equipos } = validarEquipos(d.equipos);
  if (error) throw new Error(error);
  const username = await usernameLibreFormulario(env, d.nombre, equipos);
  const password = generatePassword();
  const salt = randomSalt();
  const hash = await hashPassword(password, salt);
  await env.DB.prepare(
    "INSERT INTO users (username, password_hash, salt, nombre, rol, activo, email, equipo, categorias_fijas) VALUES (?, ?, ?, ?, ?, 1, ?, ?, ?)"
  ).bind(username, hash, salt, d.nombre, rol, email || null, equipos.length ? JSON.stringify(equipos) : null,
    d.categorias_fijas.length ? JSON.stringify(d.categorias_fijas) : null).run();
  return { cuenta: { username, password, nombre: d.nombre, rol, equipos, categorias_fijas: d.categorias_fijas } };
}
async function enviarCuentaPorCorreoFormulario(env, cuenta, correo) {
  if (!correo) return false;
  const enlace = `${SITIO_URL}/admin/login.html`;
  const equipo = [...cuenta.equipos, ...cuenta.categorias_fijas.map((c) => FORMULARIO_CATEGORIA_FIJA_ETIQUETA[c] || c)].join(" & ");
  const rolTxt = cuenta.rol === "fotografo" ? "fotógrafo" : "redactor";
  return enviarEmailNotificacion(env, {
    asunto: "Tu cuenta de ElOtroFútbol",
    texto: [`Hola, ${cuenta.nombre}:`, "", `Ya tienes cuenta de ${rolTxt}${equipo ? " (" + equipo + ")" : ""} en ElOtroFútbol.`,
      "", `Usuario: ${cuenta.username}`, `Contraseña: ${cuenta.password}`, "", `Entra aquí: ${enlace}`,
      "", "Guarda estos datos en un sitio seguro."].join("\n"),
    html: `<p>Hola, <strong>${escapeHtmlEmail(cuenta.nombre)}</strong>:</p>
<p>Ya tienes cuenta de ${rolTxt}${equipo ? " (" + escapeHtmlEmail(equipo) + ")" : ""} en ElOtroFútbol.</p>
<p><strong>Usuario:</strong> ${escapeHtmlEmail(cuenta.username)}<br><strong>Contraseña:</strong> ${escapeHtmlEmail(cuenta.password)}</p>
<p><a href="${enlace}">Entrar al panel</a></p><p>Guarda estos datos en un sitio seguro.</p>`,
  }, { destinatario: correo });
}
// Red de seguridad del formulario de incorporación: si por lo que sea sus campos de nombre han perdido la
// marca "alta_usuario" (no se aplicó el SQL, o se guardó el formulario desde un panel antiguo), se aplica
// igualmente: nombre_red crea redactores y nombre_fot fotógrafos. Solo actúa si NINGÚN campo tiene la marca.
const FORMULARIO_INCORPORACION_SLUG = "formulario-de-incorporacion-elotrofutbol";
const FORMULARIO_INCORPORACION_ALTA = { nombre_red: "redactor", nombre_fot: "fotografo" };
const FORMULARIO_INCORPORACION_ALIAS = { "TodosADCeuta — AD Ceuta": "ismael_adc", "Juanma — Jurisprudencia": "juanma" };
// Respuestas sin rol -> «Redactor». Las primeras respuestas del formulario de incorporación se recogieron antes de
// que existiera la pregunta «Selecciona tu rol» y quedaron sin rol; todas eran de redactores. Si una respuesta no
// trae rol (o viene vacío) se le pone «Redactor». Se aplica al listarlas, al editarlas y, de forma permanente, con
// asignar_rol_redactor_incorporacion.sql. Si ya tiene rol (Redactor o Fotógrafo) no se toca.
function rolPorDefectoIncorporacion(slug, datos) {
  if (slug !== FORMULARIO_INCORPORACION_SLUG || !datos || typeof datos !== "object" || Array.isArray(datos)) return datos;
  if (typeof datos.rol === "string" && datos.rol.trim()) return datos;
  return { ...datos, rol: "Redactor" };
}
function camposConAltaPorDefecto(slug, campos) {
  if (slug !== FORMULARIO_INCORPORACION_SLUG || campos.some((c) => c && c.alta_usuario)) return campos;
  return campos.map((c) => {
    const rol = FORMULARIO_INCORPORACION_ALTA[c && c.id];
    if (!rol || (c.tipo !== "desplegable" && c.tipo !== "opcion")) return c;
    return { ...c, alta_usuario: rol, ...(rol === "redactor" && !c.alias_usuarios ? { alias_usuarios: { ...FORMULARIO_INCORPORACION_ALIAS } } : {}) };
  });
}
// Recorre las respuestas de los formularios que tienen algún campo con alta de usuario de ese rol.
async function recorrerRespuestasAltaUsuarios(env, rol, fn) {
  const { results: forms } = await env.DB.prepare("SELECT id, slug, campos FROM formularios").all();
  for (const f of (forms || [])) {
    const ids = camposConAltaPorDefecto(f.slug, parsearCamposFormulario(f.campos)).filter((c) => c.alta_usuario === rol);
    if (!ids.length) continue;
    const { results } = await env.DB.prepare("SELECT id, datos FROM formularios_respuestas WHERE formulario_id = ?").bind(f.id).all();
    for (const r of (results || [])) {
      let datos = {};
      try { datos = JSON.parse(String(r.datos || "{}")) || {}; } catch {}
      await fn(r.id, datos, ids);
    }
  }
}
// Palabras de un nombre de formulario, sin tildes, mayúsculas ni teléfono entre paréntesis.
function palabrasNombreFormulario(t) {
  return normalizarOpcionUnica(String(t || "").replace(/\s*\([^)]*\)\s*$/, "")).split(" ").filter(Boolean);
}
// Al eliminar un usuario: fuera su respuesta del formulario. Devuelve cuántas respuestas ha borrado.
// Se busca por niveles y se para en el primero que encuentra algo:
//  1) vínculo guardado al enviar el formulario (datos._usuario = username): exacto, aunque luego se
//     hayan cambiado el nombre, el equipo o el rol de la persona;
//  2) nombre y equipo elegidos = los datos actuales del usuario (respuestas anteriores al vínculo);
//  3) mismo nombre sin mirar el equipo, solo si hay UNA respuesta candidata (le cambiaron el equipo);
//  4) un nombre contenido en el otro (le añadieron apellidos) y un equipo en común, solo si hay UNA.
// Se miran los campos de alta de TODOS los roles: si la persona cambió de rol (o ahora es admin) su
// respuesta sigue en el campo del rol con el que se dio de alta. Una respuesta vinculada a OTRO
// usuario nunca se borra por los niveles 2-4.
async function borrarRespuestasDeUsuarioFormulario(env, u, opcionesElegidasOut) {
  if (!u) return 0;
  const porId = new Map();
  for (const rol of FORMULARIO_ALTA_ROLES) {
    await recorrerRespuestasAltaUsuarios(env, rol, async (rid, datos, ids) => {
      const previa = porId.get(rid);
      if (previa) previa.campos.push(...ids); else porId.set(rid, { rid, datos, campos: [...ids] });
    });
  }
  const todas = [...porId.values()];
  const username = String(u.username || "").toLowerCase();
  const vinculo = (c) => (typeof c.datos._usuario === "string" ? c.datos._usuario.toLowerCase() : "");
  const opciones = (c) => c.campos
    .map((campo) => ({ campo, valor: c.datos[campo.id] }))
    .filter((x) => typeof x.valor === "string" && x.valor);
  let elegidas = username ? todas.filter((c) => vinculo(c) === username) : [];
  const libres = todas.filter((c) => !vinculo(c) || vinculo(c) === username);
  if (!elegidas.length) {
    elegidas = libres.filter((c) => opciones(c).some((x) => opcionCoincideConUsuarioFormulario(x.valor, u, x.campo.alias_usuarios)));
  }
  const miNombre = palabrasNombreFormulario(u.nombre);
  if (!elegidas.length && miNombre.length) {
    const iguales = libres.filter((c) => opciones(c).some((x) => palabrasNombreFormulario(datosUsuarioDesdeOpcionFormulario(x.valor).nombre).join(" ") === miNombre.join(" ")));
    if (iguales.length === 1) elegidas = iguales;
  }
  if (!elegidas.length && miNombre.length) {
    const misEquipos = parsearEquipos(u.equipo).map(normalizarOpcionUnica);
    const misCategorias = parsearCategoriasFijas(u.categorias_fijas);
    const contenidos = libres.filter((c) => opciones(c).some((x) => {
      const d = datosUsuarioDesdeOpcionFormulario(x.valor);
      const suyo = palabrasNombreFormulario(d.nombre);
      if (!suyo.length) return false;
      const unoEnOtro = suyo.every((p) => miNombre.includes(p)) || miNombre.every((p) => suyo.includes(p));
      const equipoComun = d.equipos.some((e) => misEquipos.includes(normalizarOpcionUnica(e))) || d.categorias_fijas.some((k) => misCategorias.includes(k));
      return unoEnOtro && equipoComun;
    }));
    if (contenidos.length === 1) elegidas = contenidos;
  }
  for (const c of elegidas) {
    if (Array.isArray(opcionesElegidasOut)) for (const x of opciones(c)) opcionesElegidasOut.push(x.valor);
    await env.DB.prepare("DELETE FROM formularios_respuestas WHERE id = ?").bind(c.rid).run();
  }
  return elegidas.length;
}

// Al eliminar un usuario, su nombre también sale de la lista «Selecciona tu nombre» de los formularios con alta
// de usuario (y de sus invitaciones sueltas): antes solo se borraba su respuesta y la opción volvía a la lista.
// Se reconoce la opción igual que al dar de alta (alias explícito, o mismo nombre y equipo/categoría) y, además,
// la que eligió en las respuestas borradas (extra). Los campos con "fuente" (lista viva desde usuarios) no tienen
// opciones fijas: se actualizan solos. Devuelve cuántas opciones ha quitado.
async function quitarNombreDeUsuarioFormularios(env, u, extra = []) {
  if (!u) return 0;
  const { results: forms } = await env.DB.prepare("SELECT id, slug, campos FROM formularios").all();
  const claveExtra = new Set((extra || []).map((x) => normalizarOpcionUnica(x)));
  let quitadas = 0;
  for (const f of (forms || [])) {
    const crudos = parsearCamposFormulario(f.campos);
    const conAlta = camposConAltaPorDefecto(f.slug, crudos);
    const coincide = (op, alta) => typeof op === "string"
      && ((alta.alta_usuario === u.rol && opcionCoincideConUsuarioFormulario(op, u, alta.alias_usuarios)) || claveExtra.has(normalizarOpcionUnica(op)));
    let cambiado = false;
    const nuevos = crudos.map((c, i) => {
      const alta = conAlta[i];
      if (!c || !alta || !FORMULARIO_ALTA_ROLES.includes(String(alta.alta_usuario || "")) || !Array.isArray(c.opciones) || !c.opciones.length) return c;
      const quedan = c.opciones.filter((op) => !coincide(op, alta));
      if (quedan.length === c.opciones.length) return c;
      quitadas += c.opciones.length - quedan.length;
      cambiado = true;
      return { ...c, opciones: quedan };
    });
    if (cambiado) {
      await env.DB.prepare("UPDATE formularios SET campos = ?, updated_at = datetime('now') WHERE id = ?").bind(JSON.stringify(nuevos), f.id).run();
    }
    // Invitaciones sueltas ("Personas invitadas") de esa persona en los campos con alta de usuario.
    try {
      const { results: inv } = await env.DB.prepare("SELECT id, campo_id, opcion FROM formularios_invitados WHERE formulario_id = ?").bind(f.id).all();
      for (const i of (inv || [])) {
        const alta = conAlta.find((c) => c && c.id === i.campo_id && FORMULARIO_ALTA_ROLES.includes(String(c.alta_usuario || "")));
        if (!alta || !coincide(i.opcion, alta)) continue;
        await env.DB.prepare("DELETE FROM formularios_invitados WHERE id = ?").bind(i.id).run();
        quitadas++;
      }
    } catch (e) {
      if (!/no such table|does not exist/i.test(String((e && e.message) || e))) throw e; // sin la tabla (migración sin aplicar) no hay invitaciones
    }
  }
  return quitadas;
}
async function obtenerFormularioPublico(env, slug) {
  const s = String(slug || "").toLowerCase();
  if (!/^[a-z0-9-]{1,60}$/.test(s)) return null;
  const f = await env.DB.prepare(
    "SELECT id, slug, titulo, descripcion, aviso, texto_boton, mensaje_final, campos, acceso, pin, activo, notificar_email FROM formularios WHERE slug = ?"
  ).bind(s).first();
  if (!f || !Number(f.activo)) return null;
  return f;
}
function comprobarAccesoFormulario(f, pinRecibido) {
  if (f.acceso !== "pin") return { ok: true };
  if (!f.pin) return { ok: false, status: 403, error: "Este formulario todavía no está disponible" };
  if (!pinAcreditacionCorrecto(String(f.pin), String(pinRecibido || "").trim())) return { ok: false, status: 401, error: "PIN incorrecto" };
  return { ok: true };
}
// Valida las respuestas de un visitante contra los campos del formulario.
// Devuelve { datos, resumen } o { error }.
function validarRespuestasFormulario(campos, recibidas, opts = {}) {
  const r = recibidas && typeof recibidas === "object" ? recibidas : {};
  const datos = {};
  for (const c of campos) {
    if (FORMULARIO_TIPOS_SIN_RESPUESTA.includes(c.tipo)) continue;
    // Campo condicional oculto: no se exige ni se guarda (se evalúa contra lo ya validado).
    if (c.mostrar_si) {
      const ref = datos[c.mostrar_si.campo];
      const visible = Array.isArray(ref) ? ref.includes(c.mostrar_si.igual) : ref === c.mostrar_si.igual;
      if (!visible) continue;
    }
    const v = r[c.id];
    const vacio = (v === undefined || v === null || v === "" || (Array.isArray(v) && !v.length) || v === false);
    if (vacio) {
      if (c.obligatorio && opts.estricto !== false) return { error: c.tipo === "confirmacion" ? `Debes marcar: ${c.etiqueta}` : `Falta responder: ${c.etiqueta}` };
      continue;
    }
    switch (c.tipo) {
      case "texto": datos[c.id] = formularioLimpiarTexto(v, 500); break;
      case "parrafo": datos[c.id] = formularioLimpiarParrafo(v, 4000); break;
      case "email": {
        const e = formularioLimpiarTexto(v, 200).toLowerCase();
        if (!emailValido(e)) return { error: `Correo no válido en: ${c.etiqueta}` };
        datos[c.id] = e; break;
      }
      case "telefono": {
        const t = formularioLimpiarTexto(v, 30);
        if (!/^[+()\d\s.-]{6,30}$/.test(t)) return { error: `Teléfono no válido en: ${c.etiqueta}` };
        datos[c.id] = t; break;
      }
      case "numero": {
        const n = Number(String(v).replace(",", "."));
        if (!Number.isFinite(n) || Math.abs(n) > 1e12) return { error: `Número no válido en: ${c.etiqueta}` };
        datos[c.id] = n; break;
      }
      case "fecha": {
        const t = formularioLimpiarTexto(v, 10);
        if (!/^\d{4}-\d{2}-\d{2}$/.test(t) || Number.isNaN(Date.parse(t))) return { error: `Fecha no válida en: ${c.etiqueta}` };
        datos[c.id] = t; break;
      }
      case "desplegable":
      case "opcion": {
        const t = formularioLimpiarTexto(v, 300);
        if (c.opciones.includes(t)) { datos[c.id] = t; break; }
        if (c.permitir_otro && t.startsWith("Otro: ") && t.length > 6) { datos[c.id] = t; break; }
        if (c.invitaciones) return { error: `«${t}» ya no está disponible en: ${c.etiqueta}. Puede que tu invitación haya caducado: recarga la página o pide que te la renueven.` };
        return { error: `Opción no válida en: ${c.etiqueta}` };
      }
      case "casillas": {
        const arr = Array.isArray(v) ? v : [v];
        const sel = [...new Set(arr.map((x) => formularioLimpiarTexto(x, 300)))].filter(Boolean);
        if (!sel.length) { if (c.obligatorio) return { error: `Falta responder: ${c.etiqueta}` }; break; }
        if (sel.some((x) => !c.opciones.includes(x))) return { error: `Opción no válida en: ${c.etiqueta}` };
        datos[c.id] = sel; break;
      }
      case "confirmacion": datos[c.id] = v === true; break;
      default: break;
    }
  }
  return { datos };
}
function datosFormularioParaTexto(campos, datos) {
  return campos.filter((c) => datos[c.id] !== undefined).map((c) => {
    const v = datos[c.id];
    const t = Array.isArray(v) ? v.join(", ") : (v === true ? "Sí" : String(v));
    return { etiqueta: c.etiqueta, valor: t };
  });
}

// PIN de acceso al formulario público de acreditaciones. Se guarda en
// settings (clave "acreditacion_pin") y lo gestiona un admin desde
// Solicitudes > Formularios > Acreditaciones. Sin PIN configurado el formulario
// queda cerrado; la primera vez que un admin abre esa pestaña se genera uno.
const ACREDITACION_PIN_KEY = "acreditacion_pin";
function validarPinAcreditacion(pin) {
  return typeof pin === "string" && /^\d{4,8}$/.test(pin);
}
function generarPinAcreditacion() {
  const arr = new Uint32Array(1);
  crypto.getRandomValues(arr);
  return String(arr[0] % 1000000).padStart(6, "0");
}
async function obtenerPinAcreditacion(env) {
  const row = await env.DB.prepare("SELECT value FROM settings WHERE key = ?").bind(ACREDITACION_PIN_KEY).first();
  return row && row.value ? String(row.value) : null;
}
async function guardarPinAcreditacion(env, pin) {
  await env.DB.prepare(
    "INSERT INTO settings (key, value, updated_at) VALUES (?, ?, datetime('now')) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at"
  ).bind(ACREDITACION_PIN_KEY, pin).run();
}
function pinAcreditacionCorrecto(esperado, recibido) {
  if (!esperado || typeof recibido !== "string" || recibido.length !== esperado.length) return false;
  let diff = 0;
  for (let i = 0; i < esperado.length; i++) diff |= esperado.charCodeAt(i) ^ recibido.charCodeAt(i);
  return diff === 0;
}

// Modo de acceso al formulario público de acreditaciones (lo elige un admin):
//   "pin"      -> hay que introducir el PIN (por defecto, como siempre)
//   "login"    -> hay que iniciar sesión con una cuenta de colaborador (admin/redactor/fotógrafo)
//   "solicitar"-> sin PIN ni cuenta: cualquiera puede enviar su solicitud directamente
// Se guarda en settings (clave "acreditacion_acceso").
const ACREDITACION_ACCESO_KEY = "acreditacion_acceso";
const ACREDITACION_ACCESOS = ["pin", "login", "solicitar"];
async function obtenerAccesoAcreditacion(env) {
  try {
    const row = await env.DB.prepare("SELECT value FROM settings WHERE key = ?").bind(ACREDITACION_ACCESO_KEY).first();
    const v = row && row.value ? String(row.value) : "";
    if (ACREDITACION_ACCESOS.includes(v)) return "login"; // el modo guardado se ignora: siempre cuenta + Nivel 2
  } catch {}
  return "login";
}
async function guardarAccesoAcreditacion(env, modo) {
  await env.DB.prepare(
    "INSERT INTO settings (key, value, updated_at) VALUES (?, ?, datetime('now')) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at"
  ).bind(ACREDITACION_ACCESO_KEY, modo).run();
}
// Las acreditaciones SOLO se piden con cuenta de colaborador y a partir del Nivel 2:
//  - Responsables (admin): siempre.
//  - Redactores: Nivel 2 (Aprendiz) o superior.
//  - Fotógrafos: todos, sea cual sea su nivel (F1 o F2; su escala es propia y no cuenta como editorial).
// Sin sesión no entra nadie (ya no hay PIN ni acceso libre) y cualquier otro rol queda fuera.
// El nivel se mira en la base (no en el JWT) para que un ascenso o descenso valga al momento.
const ACREDITACION_NIVEL_MINIMO_REDACTOR = 2;
async function comprobarAccesoAcreditacion(request, env, _pinRecibido) {
  const modo = "login";
  const sinSesion = { ok: false, status: 401, modo, motivo: "sin_sesion", error: "Inicia sesión con tu cuenta de colaborador para rellenar el formulario." };
  if (!(request.headers.get("Authorization") || "").startsWith("Bearer ")) return sinSesion;
  let payload = null;
  try { payload = await requireAuth(request, env); } catch {}
  if (!payload || !payload.uid) return sinSesion;
  let u = null;
  try { u = await env.DB.prepare("SELECT id, nombre, username, email, rol, nivel, activo FROM users WHERE id = ?").bind(payload.uid).first(); } catch {}
  if (!u || u.activo === 0) return sinSesion;
  const nivel = Math.max(1, Number(u.nivel) || 1);
  const usuario = { nombre: u.nombre || u.username || "", email: u.email || "", rol: u.rol, nivel: u.rol === "admin" ? NIVEL_MAXIMO : nivel };
  if (u.rol === "admin") return { ok: true, modo, usuario };
  if (u.rol === "fotografo") return { ok: true, modo, usuario };
  if (u.rol === "redactor" && nivel >= ACREDITACION_NIVEL_MINIMO_REDACTOR) return { ok: true, modo, usuario };
  if (u.rol !== "redactor") {
    return { ok: false, status: 403, modo, motivo: "rol", error: "Las acreditaciones solo las solicitan Responsables, fotógrafos y redactores a partir del Nivel 2." };
  }
  const bloqueo = { nivel, nivel_minimo: ACREDITACION_NIVEL_MINIMO_REDACTOR, rol: u.rol, nombre: usuario.nombre };
  {
    try {
      const info = NIVELES_INFO[ACREDITACION_NIVEL_MINIMO_REDACTOR] || {};
      bloqueo.nombre_nivel_minimo = info.nombre || "Aprendiz";
      const prog = calcularProgresoNivel(await contarPublicacionesPorTipo(env, u.id), NIVELES_REQUISITOS[ACREDITACION_NIVEL_MINIMO_REDACTOR]);
      bloqueo.progreso = prog.detalle;
    } catch (err) { console.error("acreditación: progreso de nivel no disponible", err); }
  }
  return {
    ok: false, status: 403, modo, motivo: "nivel", bloqueo,
    error: "Las acreditaciones se pueden solicitar a partir del Nivel 2 (Aprendiz). Sigue publicando para subir de nivel.",
  };
}

// Tipos de acreditación que acepta el formulario público (acreditacion.html).
// Deben coincidir con las opciones de esa página.
const ACREDITACION_TIPOS_ACREDITACION = [
  "Prensa / Pupitre",
  "Fotógrafo / Césped",
  "Cabina de prensa (si el club dispone de ella)",
];

// Correo al solicitante cuando un admin aprueba o rechaza su acreditación:
// resultado, datos de la solicitud y, si se aprueba, dónde y cuándo recogerla.
// Es un extra: si falla, la resolución ya está guardada.
// Máximo de caracteres de «dónde/cuándo recogerla» y de las indicaciones/mensaje de una acreditación.
const ACRED_MAX_INDICACION = 3000;
// ===== Feedback de revisores (article_feedback) =====
// Aviso al autor (y coautor) cuando alguien revisa su pieza: la aprueba
// (publica), la programa o la devuelve a borrador pidiendo cambios, con una
// nota breve opcional. Tambien admite observaciones sueltas. Ver
// migracion_article_feedback.sql. NUNCA debe romper el guardado de la noticia.
const FEEDBACK_TIPOS = ["aprobada", "programada", "cambios", "observacion"];
const FEEDBACK_NOTA_MAX = 500;

function limpiarNotaFeedback(v) {
  if (typeof v !== "string") return "";
  return v.replace(/<[^>]*>/g, "").replace(/\r/g, "").replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim().slice(0, FEEDBACK_NOTA_MAX);
}

async function enviarCorreoFeedbackArticulo(env, { destinatario, tipo, titulo, nota, revisorNombre }) {
  if (!destinatario || !destinatario.email) return false;
  const etiquetas = { aprobada: "Pieza aprobada", programada: "Pieza programada", cambios: "Cambios solicitados", observacion: "Nueva observación" };
  const intros = {
    aprobada: `${revisorNombre} ha aprobado y publicado tu pieza "${titulo}". ¡Enhorabuena!`,
    programada: `${revisorNombre} ha aprobado tu pieza "${titulo}" y la ha programado para publicarse.`,
    cambios: `${revisorNombre} ha devuelto tu pieza "${titulo}" a borrador con comentarios para que la revises.`,
    observacion: `${revisorNombre} te ha dejado una observación sobre "${titulo}".`,
  };
  const intro = intros[tipo] || intros.observacion;
  const colores = { aprobada: "#1b7f3b", programada: "#1f6feb", cambios: "#b7791f", observacion: "#7c3aed" };
  const bloque = nota
    ? `<div style="margin:0 0 14px;padding:14px 16px;background:#f5f7fa;border-left:4px solid ${colores[tipo] || "#8a93a3"};border-radius:8px;color:#2b3445;"><strong style="display:block;margin-bottom:4px;">Nota de ${escapeHtmlEmail(revisorNombre)}</strong>${escapeHtmlEmail(nota).replace(/\n/g, "<br>")}</div>`
    : "";
  const texto = [`Hola ${destinatario.nombre || ""},`, "", intro, ...(nota ? ["", `Nota de ${revisorNombre}:`, nota] : []), "", `Verlo en el panel: ${SITIO_URL}/admin/panel.html?ir=feedback`, "", "Equipo de ElOtroFútbol"].join("\n");
  const html = plantillaEmail({
    etiqueta: etiquetas[tipo] || "Feedback",
    titulo,
    tono: tipo === "cambios" ? "error" : "exito",
    preheader: intro,
    parrafo: intro,
    bloqueHtml: bloque,
    boton: { texto: "Ver mi feedback", url: escapeHtmlEmail(`${SITIO_URL}/admin/panel.html?ir=feedback`) },
  });
  return enviarEmailNotificacion(env, { asunto: `${etiquetas[tipo] || "Feedback"}: ${titulo}`, texto, html }, { destinatario: destinatario.email, replyTo: EMAIL_NOTIFICACIONES });
}

// Crea una fila por destinatario (autor y coautor, sin repetir ni avisar al
// propio revisor) y manda el correo. Devuelve cuántas filas ha creado.
async function crearFeedbackArticulo(env, { articulo, destinatariosIds, tipo, nota, revisor }) {
  try {
    if (!FEEDBACK_TIPOS.includes(tipo)) return 0;
    const ids = [...new Set((destinatariosIds || []).filter((x) => Number.isInteger(x) && x > 0 && x !== revisor.uid))];
    const notaLimpia = limpiarNotaFeedback(nota);
    let creadas = 0;
    for (const uid of ids) {
      await env.DB.prepare(
        "INSERT INTO article_feedback (article_id, article_titulo, article_slug, destinatario_id, autor_feedback_id, autor_feedback_nombre, tipo, nota) VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
      ).bind(articulo.id || null, String(articulo.titulo || "").slice(0, 300), articulo.slug || null, uid, revisor.uid || null, String(revisor.nombre || "Revisión").slice(0, 120), tipo, notaLimpia || null).run();
      creadas++;
      const dest = await env.DB.prepare("SELECT nombre, email FROM users WHERE id = ?").bind(uid).first();
      await enviarCorreoFeedbackArticulo(env, { destinatario: dest, tipo, titulo: articulo.titulo || "Tu pieza", nota: notaLimpia, revisorNombre: revisor.nombre || "Un revisor" });
    }
    return creadas;
  } catch (err) {
    console.error("feedback (crear):", err && err.message);
    return 0;
  }
}

async function enviarCorreoResolucionAcreditacion(env, a, estado, { recogida, mensaje } = {}) {
  if (!a || !a.email) return false;
  const aprobada = estado === "aprobada";
  const nl2br = (t) => escapeHtmlEmail(t).replace(/\n/g, "<br>");
  const filas = [
    ["Nombre", a.nombre], ["Equipo", a.equipo], ["Evento", a.tipo_evento],
    ["Acreditación", a.tipo_acreditacion], ["Jornada y partido", a.jornada_partido],
  ].filter(([, v]) => v);
  const asunto = aprobada
    ? `Acreditación aprobada: ${a.equipo || "ElOtroFútbol"}${a.jornada_partido ? " · " + a.jornada_partido : ""}`
    : `Sobre tu solicitud de acreditación: ${a.equipo || "ElOtroFútbol"}`;
  const intro = aprobada
    ? `Hola ${a.nombre || ""}, tu solicitud de acreditación ha sido APROBADA.`
    : `Hola ${a.nombre || ""}, lamentamos comunicarte que tu solicitud de acreditación no ha podido ser aprobada en esta ocasión.`;
  const cierre = aprobada
    ? "Recuerda que la concesión final de la acreditación corresponde siempre al club organizador."
    : "Puedes volver a solicitarla en el futuro desde el formulario. Gracias por tu interés en cubrir con ElOtroFútbol.";
  const texto = [
    intro, "",
    ...filas.map(([k, v]) => `${k}: ${v}`),
    ...(aprobada && recogida ? ["", "Dónde y cuándo recogerla:", recogida] : []),
    ...(mensaje ? ["", aprobada ? "Instrucciones:" : "Motivo / mensaje:", mensaje] : []),
    "", cierre, "", "Equipo de ElOtroFútbol",
  ].join("\n");
  const bloques = [];
  if (aprobada && recogida) {
    bloques.push(`<div style="margin:0 0 14px;padding:14px 16px;background:#e8f6ed;border-left:4px solid #1b7f3b;border-radius:8px;color:#14532d;"><strong style="display:block;margin-bottom:4px;">Dónde y cuándo recogerla</strong>${nl2br(recogida)}</div>`);
  }
  if (mensaje) {
    bloques.push(`<div style="margin:0 0 14px;padding:14px 16px;background:#f5f7fa;border-left:4px solid #8a93a3;border-radius:8px;color:#2b3445;"><strong style="display:block;margin-bottom:4px;">${aprobada ? "Instrucciones" : "Motivo / mensaje"}</strong>${nl2br(mensaje)}</div>`);
  }
  bloques.push(`<p style="margin:4px 0 0;font-size:14px;line-height:1.6;color:#5a6270;">${escapeHtmlEmail(cierre)}</p>`);
  const html = plantillaEmail({
    etiqueta: "Acreditaciones",
    titulo: aprobada ? "Acreditación aprobada" : "Solicitud no aprobada",
    tono: aprobada ? "exito" : "error",
    preheader: intro,
    parrafo: intro,
    filas: filas.map(([k, v]) => ({ etiqueta: k, valor: v })),
    bloqueHtml: bloques.join(""),
    pieHtml: "Equipo de ElOtroFútbol. Puedes responder a este correo si tienes cualquier duda.",
  });
  return enviarEmailNotificacion(env, { asunto, texto, html }, { destinatario: a.email, replyTo: EMAIL_NOTIFICACIONES });
}

// Correo con indicaciones (dónde/cuándo recoger, instrucciones) SIN cambiar el
